package edu.sharespace;
import edu.sharespace.Domain.*;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;import java.time.OffsetDateTime;import java.util.List;
interface UserRepository extends JpaRepository<User,Long>{@Lock(LockModeType.PESSIMISTIC_WRITE) @org.springframework.data.jpa.repository.Query("select u from User u where u.id=:id") java.util.Optional<User> findByIdForUpdate(@Param("id") Long id);java.util.Optional<User> findByEmail(String email);}
interface ResourceRepository extends JpaRepository<Resource,Long>{List<Resource> findByStatus(String status);@Lock(LockModeType.PESSIMISTIC_WRITE) @org.springframework.data.jpa.repository.Query("select r from Resource r where r.id=:id") java.util.Optional<Resource> findByIdForUpdate(@Param("id") Long id);}
interface BookingRepository extends JpaRepository<Booking,Long>{@Lock(LockModeType.PESSIMISTIC_WRITE) @org.springframework.data.jpa.repository.Query("select b from Booking b where b.id=:id") java.util.Optional<Booking> findByIdForUpdate(@Param("id") Long id);List<Booking> findByRequesterIdOrderByCreatedAtDesc(Long id);List<Booking> findAllByOrderByCreatedAtDesc();boolean existsByRequesterIdAndStatusIn(Long id,List<BookingStatus> states);List<Booking> findByResourceIdAndStatusInAndStartTimeLessThanAndEndTimeGreaterThan(Long id,List<BookingStatus> states,OffsetDateTime end,OffsetDateTime start);List<Booking> findByResourceIdAndStatusOrderByCreatedAtAscIdAsc(Long id,BookingStatus status);}
interface ConditionRepository extends JpaRepository<ConditionReport,Long>{List<ConditionReport> findByBookingIdOrderByCreatedAtAsc(Long id);boolean existsByBookingIdAndReportType(Long id,ReportType type);}
interface IncidentRepository extends JpaRepository<Incident,Long>{@Lock(LockModeType.PESSIMISTIC_WRITE) @org.springframework.data.jpa.repository.Query("select i from Incident i where i.id=:id") java.util.Optional<Incident> findByIdForUpdate(@Param("id") Long id);List<Incident> findAllByOrderByCreatedAtDesc();}
interface AuditRepository extends JpaRepository<AuditEvent,Long>{List<AuditEvent> findByEntityTypeAndEntityIdOrderByTimestampAsc(String type,Long id);List<AuditEvent> findAllByOrderByTimestampDesc();}
